window.VO = [{"id":"s01","text":"Butter chicken was invented by Kundan Lal.","at":0.5,"t0":0.25,"t1":2.96},{"id":"s02","text":"There's just one problem. There were two of them.","at":6.62,"t0":3.31,"t1":5.84},{"id":"s03","text":"Kundan Lal Gujral and Kundan Lal Jaggi. Two friends from Peshawar.","at":12.68,"t0":6.34,"t1":10.49},{"id":"s04","text":"Partition brought them to Delhi, where they ran one restaurant together: Moti Mahal.","at":22.28,"t0":11.14,"t1":15.97},{"id":"s05","text":"Its butter chicken got so famous, even Nehru came to eat.","at":32.84,"t0":16.42,"t1":20.005},{"id":"s06","text":"Today, their families run rival restaurants.","at":40.91,"t0":20.455,"t1":23.065},{"id":"s07","text":"And since twenty twenty-four, they've been in court over who invented butter chicken.","at":46.93,"t0":23.465,"t1":27.705},{"id":"s08","text":"The lawsuit is two thousand seven hundred and fifty-two pages long.","at":56.31,"t0":28.155,"t1":32.125},{"id":"s09","text":"The Gujral family says: Peshawar. Leftover chicken, saved in a gravy for the next day.","at":65.35,"t0":32.675,"t1":38.24},{"id":"s10","text":"The Jaggi family says: Delhi. Late guests, and not enough chicken.","at":77.48,"t0":38.74,"t1":42.5},{"id":"s11","text":"Too much chicken, or too little. Either way, the root cause was leftovers.","at":85.9,"t0":42.95,"t1":47.47},{"id":"s12","text":"Nearly three years on, the court still hasn't decided.","at":96.04,"t0":48.02,"t1":51.04},{"id":"s13","text":"But whoever wins, one thing is certain.","at":103.48,"t0":51.74,"t1":54.055},{"id":"s14","text":"Butter chicken was invented by Kundan Lal.","at":109.51,"t0":54.755,"t1":57.61}];
